        "participant_roles": ["person", "refreshment_cup", "plate", "surface"],
        "operation_count": 2
      },
      {
        "id": "position_remote",
        "operation": "Move the remote control to a shared surface accessible to both people.",
        "participant_roles": ["remote_control", "surface", "person", "person"],
        "operation_count": 1
      }
    ]
  },
